def get_user_input():
    """Get user input for the operation and the numbers."""
    operation = input("Enter the operation (+, -, *, /): ").strip()
    numbers = input("Enter the numbers separated by space: ").strip().split()
    return operation, int(numbers[0]), int(numbers[1])

def add(a, b):
    """Perform addition."""
    return a + b

def subtract(a, b):
    """Perform subtraction."""
    return a - b

def multiply(a, b):
    """Perform multiplication."""
    return a * b

def divide(a, b):
    """Perform division."""
    if b == 0:
        raise ValueError("Cannot divide by zero.")
    return a / b

def main():
    """Main function that takes user input and performs the operation."""
    operation, a, b = get_user_input()

    if operation == '+':
        result = add(a, b)
