        result = subtract(a, b)
    elif operation == '*':
        result = multiply(a, b)
    elif operation == '/':
        try:
            result = divide(a, b)
        except ValueError as e:
            print(e)
            return
    else:
        print("Invalid operation. Please enter +, -, *, or /.")
        return

    print(f"{a} {operation} {b} = {result}")

if __name__ == "__main__":
    main()
